from lib import *
S = SS('v56')
steps = [
    step("换配置的三种写法。配置里有必须一起变的两个字段 A 和 B(B 恒等于 A 的两倍),写入方每约 200 µs 发布一份新配置,8 个读取方不停地读并检查。写 A 与写 B 之间没有间隔时:原地改字段(inplace)读了 11230556362 次,读到违反的有 4471 次;atomic.Pointer 整体换只读快照(atomic)读了 11196829624 次,违反 0 次;用 RWMutex 保护原地改(rwmutex)只读了 20215188 次,违反 0 次。两次写之间隔 50 µs(模拟中间还要解析下一个配置项)时:inplace 读到违反的有 1754003571 次(读取总数 11294085910),atomic 和 rwmutex 仍然是 0。用 go build -race 构建、间隔 0 µs 跑 0.5 s:inplace 被竞态检测器报告了 2 次 “WARNING: DATA RACE”,atomic 和 rwmutex 是 0。", t=tl(S(1)), mark=lidx(S(1), 'inplace'), done=lidx(S(1), 'atomic', 'rwmutex'), b=bars([['inplace 间隔 50 µs:违反次数', 1754003571, '1754003571'], ['inplace 间隔 0:违反次数', 4471, '4471'], ['atomic 违反次数', 0, '0'], ['rwmutex 违反次数', 0, '0']], 1754003571, mark=[0, 1], done=[2, 3]), kv=KV([['原地改字段', '间隔 0:4471 次违反;间隔 50 µs:1754003571 次'], ['竞态检测器', 'inplace 报告 2 次 DATA RACE'], ['atomic 换指针', '0 次违反,读取次数与 inplace 相当'], ['RWMutex', '0 次违反,读取只有 20215188 次']], ['原地改字段'])),
    step("哪些配置换了之后会立刻生效。服务启动时是版本 1,运行中用 atomic.Pointer 换成版本 2(限速 200、worker 8 个、监听地址换成 127.0.0.1:1)。(a)请求处理里每次读配置:一共 12549 个请求,换完指针之后发起的请求里仍然用旧版本的有 0 个,第一个读到新版本的请求发起于换指针之后 0.033 ms。(b)监听地址:换配置之后原来的地址还能访问(返回 true:v2),配置里的新地址 refused。(c)按配置启动时起的 worker 是 4 个,配置改成 8 个但没有调用 Resize,500 ms 后仍是 4 个;调用 Resize(8) 后变成 8 个,用时小于 1 µs;每个任务 100 ms、队列里还有任务时,Resize(2) 到只剩 2 个 worker 用了 255.286 ms。", t=tl(S(2)), mark=lidx(S(2), '(b)', '(c)启动时', '8 → 2'), done=lidx(S(2), '(a)', '4 → 8'), b=bars([['换指针后仍用旧版本的请求', 0, '0'], ['配置改成 8 个 worker 后的实际数量', 4, '4'], ['Resize(8) 后的实际数量', 8, '8'], ['Resize(2) 缩小用时 ms', 255.286, '255.286']], 260, done=[0, 2], mark=[1, 3]), kv=KV([['每次请求读的值', '换指针后立刻生效(0 个旧版本请求)'], ['监听地址', '换配置不会换已经绑定的地址'], ['worker 数', '启动时用一次,换配置不会变;要写 Resize'], ['缩小 worker 池', '要等在忙的 worker,255.286 ms']], ['监听地址'])),
    step("坏配置推送的后果。限速 100 次/秒、客户端约 300 次/秒请求,正常时约 200 次/秒被拒绝(推送之前的数据是 199/360 左右)。推送之后 1 s:naive_ignore_err(解析出错也把零值存进去)在 bad_json 和 zero 上被拒绝 299/299 和 300/300,生效的限速是 0;在 huge(限速写成 1000000)上被拒绝 0/300,限速变成 1000000。naive_no_range(解析出错保留旧配置,但不检查范围):bad_json 保住了(200/300,限速 100),zero 被拒绝 300/300,huge 被拒绝 0/300。validated(出错或不在 1 到 10000 就保留旧配置):三种推送后限速都还是 100,被拒绝 201/300、200/300、200/300。", t=tl(S(3)), mark=lidx(S(3), 'naive_ignore_err', 'naive_no_range'), done=lidx(S(3), 'validated'), b=bars([['naive_ignore_err + zero:被拒绝', 300, '300/300'], ['naive_no_range + zero:被拒绝', 300, '300/300'], ['naive_no_range + huge:被拒绝', 0, '0/300(限速失效)'], ['validated + zero:被拒绝', 200, '200/300(同推送前)']], 300, mark=[0, 1, 2], done=[3]), kv=KV([['解析出错存零值', '限速变 0:全部拒绝'], ['不检查范围', 'zero 全部拒绝,huge 限速失效'], ['validated', '三种坏配置后限速仍是 100']], ['不检查范围'])),
    step("触发重载的方式与延迟。Go 程序用 signal.Notify 接 SIGHUP,外部 kill -HUP 200 次:收到 200/200,从发信号到处理函数拿到信号的延迟 0.030 / 0.164 / 0.513 ms(最小 / 中位 / 最大)。程序按固定间隔轮询配置文件内容,外部在随机时刻原子替换文件 30 次:轮询间隔 100 ms,发现 30/30,延迟 4.2 / 54.4 / 102.2 ms;轮询间隔 1000 ms,只发现 19/30(其余变更在一个间隔内被合并),延迟 7.3 / 409.3 / 969.3 ms。", t=tl(S(4)), mark=lidx(S(4), '1000 ms'), done=lidx(S(4), 'SIGHUP', '100 ms'), b=bars([['SIGHUP:中位 ms', 0.164, '0.164'], ['轮询 100 ms:中位 ms', 54.4, '54.4'], ['轮询 1000 ms:中位 ms', 409.3, '409.3']], 410, done=[0, 1], mark=[2]), kv=KV([['SIGHUP', '200/200,中位 0.164 ms,但不带内容'], ['轮询 100 ms', '30/30,中位 54.4 ms'], ['轮询 1000 ms', '19/30(其余被合并),中位 409.3 ms']], ['轮询 1000 ms'])),
]
